<script setup lang="ts">
import UiSelect from './UiSelect.vue'
import BatchSources from './BatchSources.vue'
import {classLabel,sortedClasses} from './classPresentation'
import {ref,computed,onMounted,watch} from 'vue'
import {Search,Download,LoaderCircle} from 'lucide-vue-next'
import {api,query,downloadFile} from './api'
import {useFeedback} from './feedback'
import { teacherLabel } from './modules'
import FieldError from './FieldError.vue'
import {useFormValidation,yearError} from './formValidation'
import {defaultTeachingPeriod,yearOptions} from './teachingCalendar'
type Item=Record<string,any>
const props=defineProps<{meta:Item,user?:Item}>()
const kind=ref('habit'),target=ref('student'),search=ref(''),year=ref(String(defaultTeachingPeriod('habit').year)),term=ref(''),period=ref(''),course=ref(''),time=ref(''),page=ref(1),result=ref<Item>({items:[],total:0,fields:[],averages:{}}),busy=ref(false)
const teacher=ref(''),classId=ref(''),experimental=ref('')
const {error}=useFeedback()
const filterElement=ref<HTMLElement>()
const validation=useFormValidation(()=>({year:()=>yearError(year.value,true)}))
function submit(){if(!validation.validate(filterElement.value))return;if(page.value===1)load();else page.value=1}
const kindOptions=computed(()=>Object.entries(props.meta.kinds).map(([value,s])=>({value,label:(s as Item).name.replace('数据上传','').replace('上传','')})))
const spec=computed(()=>props.meta.kinds[kind.value]),maxPage=computed(()=>Math.max(1,Math.ceil(result.value.total/30)))
function params(){return {kind:kind.value,target:target.value,search:search.value,year:year.value.trim(),term:term.value,period:period.value,class_type:classId.value?'':course.value,class_time:classId.value?'':time.value,teacher_id:teacher.value,class_id:classId.value,experimental:experimental.value,filter_options:'context'}}
function val(v:any,type=''){return v===null||v===undefined||v===''?'—':type==='percent'?v+'%':v}
let version=0
async function load(){const v=++version;if(!validation.isValid()){busy.value=false;return}busy.value=true;error.value='';try{const data=await api(`teaching/rows/?${query({...params(),offset:(page.value-1)*30})}`);if(v===version)result.value=data}catch(e){if(v===version)error.value=(e as Error).message}finally{if(v===version)busy.value=false}}
watch(kind,(next,previous)=>{if(year.value===String(defaultTeachingPeriod(previous).year))year.value=String(defaultTeachingPeriod(next).year);period.value='';course.value='';time.value='';page.value=1;load()})
watch([teacher,year,term],()=>{classId.value=''})
watch(classId,()=>{course.value='';time.value='';experimental.value=''},{flush:'sync'})
watch([target,year,term,period,course,time,teacher,classId,experimental],()=>{page.value=1;load()});watch(page,load)
async function download(){if(!validation.validate(filterElement.value))return;busy.value=true;error.value='';try{await downloadFile(`teaching/export/?${query({...params(),mode:'detail'})}`)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section ref="filterElement" class="panel workflow-panel"><form class="workflow-toolbar" novalidate @submit.prevent="submit"><label>搜索内容<UiSelect v-model="kind" aria-label="搜索内容" :options="kindOptions"/></label><label>搜索对象<UiSelect v-model="target" aria-label="搜索对象" :options="[{value:'student',label:'学生'},{value:'teacher',label:'教师'}]"/></label><label class="field search-grow">姓名<input v-model="search" :placeholder="target==='teacher'?'教师姓名、登录账号或 *':'中文名、英文名或 *'"/></label><button class="btn primary" @pointerdown="!validation.validate(filterElement) && $event.preventDefault()" :disabled="busy"><Search :size="16"/>搜索</button></form><div class="workflow-toolbar"><label class="field">年份<UiSelect v-model="year" name="year" aria-label="年份" :options="[{value:'',label:'全部年份'},...yearOptions.map(y=>({value:String(y),label:`${y} 年`}))]" :aria-invalid="!!validation.errors.year" :aria-describedby="validation.errors.year?'search-year-error':undefined" @change="validation.change('year')"/><FieldError id="search-year-error" :message="validation.errors.year"/></label><label>学期<UiSelect v-model="term" aria-label="学期" :options="[{value:'',label:'全部学期'},...['春','夏','秋','全年'].map(value=>({value,label:value==='夏'?'暑季':value}))]"/></label><label>期次<UiSelect v-model="period" aria-label="期次" :options="[{value:'',label:'全部期次'},...Array.from({length:spec.periods},(_,i)=>({value:String(i+1),label:kind==='scores'?spec.period_labels?.[i]||`考试 ${i+1}`:`第 ${i+1} ${spec.unit}`}))]"/></label><template v-if="meta.roster_enabled"><label>教师<UiSelect v-model="teacher" aria-label="搜索教师筛选" :options="[{value:'',label:'全部教师'},...meta.teachers.map((t:Item)=>({value:String(t.id),label:t.name}))]"/></label><label>班级<UiSelect wide v-model="classId" aria-label="搜索班级筛选" :options="[{value:'',label:'全部班级'},...sortedClasses(result.classes||[]).map((c:Item)=>({value:String(c.id),label:classLabel(c,{teacher:!teacher,term:!term||term==='全年',teachers:meta.teachers})}))]"/></label><label v-if="!classId">班型<UiSelect v-model="experimental" aria-label="搜索班型筛选" :options="[{value:'',label:'全部班型'},{value:'true',label:'实验班'},{value:'false',label:'普通班'}]"/></label></template><label v-if="!classId">课型<UiSelect v-model="course" aria-label="课型" :options="[{value:'',label:'全部课型'},...(result.courses||[]).map((c:string)=>({value:c,label:c}))]"/></label><label v-if="!classId">时间段<UiSelect v-model="time" aria-label="时间段" :options="[{value:'',label:'全部时间段'},...(result.times||[]).map((t:string)=>({value:t,label:t}))]"/></label><span class="toolbar-spacer"></span><button class="btn" :disabled="busy||!result.total" @click="download"><Download :size="16"/>导出筛选结果</button></div><div v-if="busy" class="loading-inline"><LoaderCircle class="spin" :size="17"/>正在查询…</div><div class="table-scroll"><table><thead><tr><th>年份／学期</th><th>期次</th><th>教师</th><th>学生</th><th>英文名</th><th>课型／时间段</th><th v-for="f in spec.fields" :key="f[0]">{{f[1]}}</th></tr></thead><tbody><tr v-for="r in result.items" :key="r.id"><td>{{r.year}} / {{r.term}}</td><td>{{r.period}}</td><td>{{teacherLabel(r,meta.teachers)}}</td><td>{{r.student_name}}</td><td>{{r.english_name||'—'}}</td><td>{{r.class_type}} / {{r.class_time}}</td><td v-for="f in spec.fields" :key="f[0]" :class="{'wrap-cell':f[0]==='content'}">{{val(r.data[f[0]],f[2])}}</td></tr><tr v-if="result.total" class="average-row"><td colspan="6">平均值（星币合计）</td><td v-for="f in spec.fields" :key="f[0]">{{val(result.averages?.[f[0]],f[2])}}</td></tr></tbody></table><div v-if="!result.total&&!busy" class="empty-state compact">暂无符合条件的已上传数据。</div></div><div class="workflow-footer"><span>共 {{result.total}} 条</span><div class="pagination"><button class="btn small" :disabled="page<=1||busy" @click="page--">上一页</button><span>{{page}} / {{maxPage}}</span><button class="btn small" :disabled="page>=maxPage||busy" @click="page++">下一页</button></div></div><BatchSources v-if="meta.roster_enabled" :records="result.items" :user="user"/></section></template>
